-- Read-only baseline extracted from TESTE on 2026-08-18.
-- Source: DBMS_METADATA supplied by the user; do not edit as deployment source.
CREATE OR REPLACE FORCE EDITIONABLE VIEW "TESTE"."AD_VGFPROVEST"
(
    "AD_SEQRESERVA", "STATUSNOTA", "ORDEM", "NUNOTA", "SEQUENCIA",
    "QTDORIGINAL", "IDIPROC", "SEQPREV", "REFERENCIA", "CODPROD",
    "DTNEG", "DHMOV", "CODUSUINC", "CODUSU", "CODVEND", "CODPARC",
    "CODTIPOPER", "DESCROPER", "DTPREVENT", "CODLOCAL",
    "QTDPENDENTE", "SALDO"
) AS
SELECT ENT.SEQENT AS AD_SEQRESERVA,
       FNC_GETSTATUSLIB_PRA(CAB.NUNOTA) AS STATUSNOTA,
       DENSE_RANK() OVER (
           PARTITION BY ITE.CODPROD
           ORDER BY ENT.SEQENT, CAB.AD_DHCONFIRMACAO, ENT.SEQENT ASC
       ) AS ORDEM,
       ITE.NUNOTA,
       ITE.SEQUENCIA,
       ITE.QTDNEG AS QTDORIGINAL,
       CAB.IDIPROC,
       ENT.SEQENT AS SEQPREV,
       PRO.REFERENCIA,
       ITE.CODPROD,
       CAB.DTNEG,
       ENT.DTLANC AS DHMOV,
       CAB.CODUSU AS CODUSUINC,
       ITE.CODUSU,
       CAB.CODVEND,
       CAB.CODPARC,
       CAB.CODTIPOPER,
       TOP.DESCROPER,
       NVL(NVL(ENT.DTPREV, CAB.DTPREVENT), '12/12/2999') AS DTPREVENT,
       ITE.CODLOCALORIG AS CODLOCAL,
       ENT.QTDENT - NVL(ENT.QTDENTREGUE, 0) AS QTDPENDENTE,
       FNC_ESTCOMERCIAL_PRA(ITE.CODPROD)
       - (SELECT SUM(E.QTDPENDENTE)
            FROM AD_VGFRESEST E
           WHERE E.CODPROD = ENT.CODPROD)
       - (SELECT SUM(E.QTDENT)
            FROM AD_TGFSEQENT E
           WHERE E.CODPROD = ENT.CODPROD
             AND E.SEQUENCIA = ENT.SEQUENCIA
             AND E.NUNOTA = ENT.NUNOTA
             AND NVL(ENT.PROVISAO, 'N') = 'S')
       - SUM(ENT.QTDENT - NVL(ENT.QTDENTREGUE, 0)) OVER (
             PARTITION BY ITE.CODPROD
             ORDER BY ENT.SEQENT
             ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
         ) AS SALDO
  FROM TGFITE ITE
  JOIN TGFCAB CAB
    ON ITE.NUNOTA = CAB.NUNOTA
  JOIN AD_TGFSEQENT ENT
    ON ENT.NUNOTA = ITE.NUNOTA
   AND ENT.SEQUENCIA = ITE.SEQUENCIA
  JOIN TGFPRO PRO
    ON ITE.CODPROD = PRO.CODPROD
  JOIN TGFTOP TOP
    ON TOP.CODTIPOPER = CAB.CODTIPOPER
   AND TOP.DHALTER = CAB.DHTIPOPER
 WHERE ITE.PENDENTE = 'S'
   AND CAB.TIPMOV IN ('P', 'J')
   AND CAB.STATUSNOTA = 'L'
   AND NVL(TOP.AD_FILARESERVA, 'N') = 'S'
   AND ENT.SEQENT IS NOT NULL
   AND ENT.QTDENT - NVL(ENT.QTDENTREGUE, 0) > 0
   AND NVL(ENT.PROVISAO, 'N') = 'S'
 ORDER BY ITE.CODPROD, ITE.AD_SEQRESERVA;
